CREATE TABLE `liqi_enterprise` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `enterprise_name` varchar(120) NOT NULL DEFAULT '' COMMENT '企业名称',
  `legal_person` varchar(32) NOT NULL DEFAULT '' COMMENT '法定代表人',
  `establish_date` date DEFAULT NULL COMMENT '成立时间',
  `registered_capital` varchar(40) NOT NULL DEFAULT '' COMMENT '注册资本',
  `insured_count` int NOT NULL DEFAULT '0' COMMENT '参保人数',
  `industry` varchar(80) NOT NULL DEFAULT '' COMMENT '所属行业',
  `register_address` varchar(200) NOT NULL DEFAULT '' COMMENT '注册地址',
  `short_name` varchar(8) NOT NULL DEFAULT '' COMMENT 'logo简称',
  `logo_color` varchar(16) NOT NULL DEFAULT '' COMMENT 'logo颜色',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `credit_code` varchar(32) DEFAULT NULL COMMENT '统一社会信用代码',
  `reg_number` varchar(32) DEFAULT NULL COMMENT '工商注册号',
  `org_number` varchar(32) DEFAULT NULL COMMENT '组织机构代码',
  `tax_number` varchar(32) DEFAULT NULL COMMENT '纳税人识别号',
  `former_name` varchar(512) DEFAULT NULL COMMENT '曾用名',
  `company_org_type` varchar(64) DEFAULT NULL COMMENT '企业类型',
  `reg_status` varchar(32) DEFAULT NULL COMMENT '经营状态',
  `actual_capital` varchar(64) DEFAULT NULL COMMENT '实缴资本',
  `staff_num_range` varchar(32) DEFAULT NULL COMMENT '人员规模',
  `reg_institute` varchar(128) DEFAULT NULL COMMENT '登记机关',
  `bond_name` varchar(64) DEFAULT NULL COMMENT '上市简称',
  `bond_num` varchar(32) DEFAULT NULL COMMENT '上市代码',
  `business_scope` text COMMENT '经营范围',
  `tags` varchar(1024) DEFAULT NULL COMMENT '企业标签（; 分隔）',
  `enrich_status` tinyint NOT NULL DEFAULT '0' COMMENT '工商回填状态：0未回填 1已回填 2查无结果',
  `enrich_time` datetime DEFAULT NULL COMMENT '最近工商回填时间',
  PRIMARY KEY (`id`),
  KEY `idx_addr` (`register_address`(32))
) ENGINE=InnoDB AUTO_INCREMENT=5140 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='力企-企业库';
